// Settings, kept in sync with config.js
const THRESH = { heatC: 50, smoke: 60 };
const MIN_DANGEROUS = 2;
const FRESHNESS_MS = 10000;
const REPUBLISH_MS = 15000;

let states = flow.get('states') || {};
const now = Date.now();

// If this is a sensor reading, update that sensor's latest state.
if (msg.topic && msg.topic.indexOf('/sensors/') !== -1) {
    try {
        const r = JSON.parse(msg.payload);
        states[r.id] = { reading: r, ts: now };
        flow.set('states', states);
    } catch (e) {
        node.warn('Bad sensor payload: ' + msg.payload);
        return null;
    }
}

// A reading is dangerous when heat AND smoke are high, or a flame is seen.
function isDangerous(r) {
    const hotAndSmoky = r.heat > THRESH.heatC && r.smoke > THRESH.smoke;
    return hotAndSmoky || r.fire === 1;
}

// Collect fresh, dangerous sensors.
const dangerousIds = [];
const readings = {};
for (const id of Object.keys(states)) {
    const s = states[id];
    if (now - s.ts <= FRESHNESS_MS && isDangerous(s.reading)) {
        dangerousIds.push(id);
        readings[id] = s.reading;
    }
}

const count = dangerousIds.length;
const alert = count >= MIN_DANGEROUS; // one sensor is never enough

const statusMsg = { payload: `dangerous=${count} [${dangerousIds.join(', ')}] alert=${alert}` };

if (!alert) {
    return [null, statusMsg];
}

// Rate-limit so we re-publish periodically instead of every message.
const last = flow.get('lastAlertTs') || 0;
if (now - last < REPUBLISH_MS) {
    return [null, statusMsg];
}
flow.set('lastAlertTs', now);

const alertObj = {
    event: 'FOREST_FIRE_CONFIRMED',
    dangerousSensors: count,
    sensorIds: dangerousIds.join(', '),
    readings: readings,
    time: new Date(now).toISOString()
};

const alertMsg = { payload: JSON.stringify(alertObj), alert: alertObj };
return [alertMsg, statusMsg];

// Shape the alert into the {value1,value2,value3} body IFTTT expects.
const a = msg.alert || {};
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    value1: String(a.dangerousSensors || ''),
    value2: a.sensorIds || '',
    value3: a.time || ''
};
return msg;
